    35  IEC104Stats::IEC104Stats() {
    36    memset(&pkt_lost, 0, sizeof(pkt_lost));
    37    last_type_i = 0;
    38    memset(&last_i_apdu, 0, sizeof(last_i_apdu));
    39    memset(&stats, 0, sizeof(stats));
    40    memset(&transitions, 0, sizeof(transitions));
    41
    42    i_s_apdu = ndpi_alloc_data_analysis(32 /* sliding window side */);
    43    tx_seq_num = rx_seq_num = 0, infobuf[0] = '\0';
    44    invalid_command_transition_detected = false;
    45  }
