    53  void IEC104Stats::processPacket(Flow *f, bool tx_direction,
    54                                  const u_char *payload, u_int16_t payload_len,
    55                                  struct timeval *packet_time) {
    56    if ((payload_len >= 6) && (payload[0] == 0x68 /* IEC magic byte */)) {
    57      u_int offset = 1 /* Skip magic byte */;
    58      u_int64_t *allowedTypeIDs = ntop->getPrefs()->getIEC104AllowedTypeIDs();
    59      std::unordered_map<u_int16_t, u_int32_t>::iterator it;
    60
    61      lock.wrlock(__FILE__, __LINE__);
    62
    63      if (tx_direction)
    64        stats.forward_msgs++;
    65      else
    66        stats.reverse_msgs++;
    67
    68      while (offset /* Skip START byte */ < payload_len) {
    69        /* https://infosys.beckhoff.com/english.php?content=../content/1033/tcplclibiec870_5_104/html/tcplclibiec870_5_104_objref_overview.htm&id
    70         */
    71        u_int8_t len = payload[offset],
    72                 pdu_type = ((payload[offset + 1] & 0x01) == 0)
    73                                ? 0
    74                                : (payload[offset + 1] & 0x03);
    75
    76  #ifdef DEBUG_IEC60870
    77        ntop->getTrace()->traceEvent(TRACE_WARNING, "[%s] %02X %02X %02X %02X",
    78                                     __FUNCTION__, payload[offset - 1],
    79                                     payload[offset], payload[offset + 1],
    80                                     payload[offset + 2]);
    81  #endif
    82
    83  #ifdef DEBUG_IEC60870
    84        ntop->getTrace()->traceEvent(
    85            TRACE_WARNING, "[%s] A-PDU Len %u/%u [pdu_type: %u][magic: %02X]",
    86            __FUNCTION__, len, payload_len, pdu_type, payload[offset - 1]);
    87  #endif
    88
    89        if (len == 0) break; /* Something went wrong */
    90
    91        switch (pdu_type) {
    92          case 0x03: /* U */
    93          {
    94            u_int8_t u_type = (payload[offset + 1] & 0xFC) >> 2;
    95            const char *u_type_str;
    96
    97  #ifdef IEC60870_TRACE
    98            ntop->getTrace()->traceEvent(TRACE_NORMAL, "A-PDU U-%u",
    99                                         (payload[offset + 1] & 0xFC) >> 2);
   100  #endif
   101            /* No rx and tx to be updated */
   102            stats.type_u++;
   103
   104            switch (u_type) {
   105              case 0x01:
   106                u_type_str = "STARTDT act";
   107                break;
   108
   109              case 0x02:
   110                u_type_str = "STARTDT con";
   111                break;
   112
   113              case 0x04:
   114                u_type_str = "STOPDT act";
   115                break;
   116
   117              case 0x08:
   118                u_type_str = "STOPDT con";
   119                break;
   120
   121              case 0x10:
   122                u_type_str = "TESTFR act";
   123                break;
   124
   125              case 0x20:
   126                u_type_str = "TESTFR con";
   127                break;
   128
   129              default:
   130                u_type_str = "???";
   131                break;
   132            }
   133
   134            snprintf(infobuf, sizeof(infobuf) - 1, "%s U (%s)",
   135                     tx_direction ? "->" : "<-", u_type_str);
   136          } break;
   137
   138          case 0x01: /* S */
   139            if (len >= 4) {
   140              u_int16_t rx = ((((u_int16_t)payload[offset + 4]) << 8) +
   141                              payload[offset + 3]) >>
   142                             1;
   143
   144              if (last_i_apdu.tv_sec != 0) {
   145                float ms = Utils::msTimevalDiff(packet_time, &last_i_apdu);
   146
   147  #ifdef IEC60870_TRACE
   148                ntop->getTrace()->traceEvent(
   149                    TRACE_NORMAL,
   150                    "A-PDU S [last I-TX: %u][S RX ack: %u][tdiff: %.2f msec]",
   151                    tx_seq_num, rx, ms);
   152  #endif
   153                /*
   154                  In theory if all is in good shape
   155                  (rx + 1) == tx_seq_num
   156                */
   157
   158                ndpi_data_add_value(i_s_apdu, ms);
   159              }
   160
   161              /* No rx and tx to be updated */
   162              snprintf(infobuf, sizeof(infobuf) - 1, "%s S, RX %u",
   163                       tx_direction ? "->" : "<-", rx);
   164            }
   165
   166            stats.type_s++;
   167            break;
   168        }
   169
   170        if (pdu_type != 0x0 /* Type I */) {
   171          offset += len + 2;
   172          stats.type_other++;
   173          continue;
   174        }
   175
   176        /* From now on, only Type I packets are processed */
   177        memcpy(&last_i_apdu, packet_time, sizeof(struct timeval));
   178        stats.type_i++;
   179
   180        if (len >= 6 /* Ignore 4 bytes APDUs */) {
   181          u_int16_t rx_value, tx_value;
   182          bool initial_run =
   183              ((rx_seq_num == 0) && (tx_seq_num == 0)) ? true : false;
   184
   185          tx_value =
   186              ((((u_int16_t)payload[offset + 2]) << 8) + payload[offset + 1]) >>
   187              1;
   188          rx_value =
   189              ((((u_int16_t)payload[offset + 4]) << 8) + payload[offset + 3]) >>
   190              1;
   191
   192          if (!tx_direction) {
   193            /* Counters are swapped */
   194            u_int16_t v = rx_value;
   195
   196            rx_value = tx_value;
   197            tx_value = v;
   198          }
   199
   200          if ((tx_value == tx_seq_num) && (rx_value == rx_seq_num)) {
   201            stats.retransmitted_msgs++;
   202            lock.unlock(__FILE__, __LINE__);
   203            return;
   204          }
   205
   206          if (!initial_run) {
   207            u_int32_t diff = abs(tx_value - (tx_seq_num + 1));
   208
   209            /* Check for id reset (16 bit only) */
   210            if (diff != 32768) pkt_lost.tx += diff;
   211          }
   212          tx_seq_num = tx_value;
   213
   214          if (!tx_direction) {
   215            if (!initial_run) {
   216              u_int32_t diff = abs(rx_value - rx_seq_num);
   217
   218              /* Check for id reset (16 bit only) */
   219              if (diff != 32768) pkt_lost.rx += diff;
   220            }
   220            }
   221
   222            rx_value++; /* The next RX will be increased by 1 */
   223          } else {
   224            if (!initial_run) {
   225              u_int32_t diff = abs(rx_value - rx_seq_num);
   226
   227              /* Check for id reset (16 bit only) */
   228              if (diff != 32768) pkt_lost.rx += diff;
   229            }
   230          }
   231          rx_seq_num = rx_value;
   232
   233          /* Skip magic(1), len(1), type/TX(2), RX(2) = 6 */
   234          len -= 6 /* Skip magic and len */,
   235              offset += 5 /* magic already skept */;
   236
   237          if (payload_len >= (offset + len)) {
   238            u_int8_t type_id = payload[offset];
   239            u_int8_t cause_tx = payload[offset + 1] & 0x3F;
   240            u_int8_t negative =
   241                ((payload[offset + 1] & 0x40) == 0x40) ? true : false;
   242            u_int16_t asdu;
   243            u_int64_t bit;
   244            bool unexpected_typeid_alerted = false;
   245
   246            offset += len + 2 /* magic and len */;
   247
   248            if (len >= 6)
   249              asdu = /* ntohs */ (*((u_int16_t *)&payload[4 + offset]));
   250            else
   251              asdu = 0;
   252
   253  #ifdef DEBUG_IEC60870
   254            ntop->getTrace()->traceEvent(
   255                TRACE_WARNING, "[%s] TypeId %u [offset %u/%u]", __FUNCTION__,
   256                type_id, offset, payload_len);
   257  #endif
   258
   259  #ifdef IEC60870_TRACE
   260            ntop->getTrace()->traceEvent(
   261                TRACE_NORMAL,
   262                "[%s] A-PDU I-%-3u [rx: %u][tx: %u][lost rx/tx: %u/%u]",
   263                tx_direction ? "->" : "<-", type_id, rx_seq_num, tx_seq_num,
   264                pkt_lost.rx, pkt_lost.tx);
   265  #endif
   266
   267            snprintf(infobuf, sizeof(infobuf) - 1, "%s I, RX %u, TX %u",
   268                     tx_direction ? "->" : "<-", rx_seq_num, tx_seq_num);
   269
   270            if (!initial_run) {
   271              u_int32_t transition = (last_type_i << 8) + type_id;
   272
   273              it = type_i_transitions.find(transition);
   274
   275              if (it == type_i_transitions.end()) {
   276                if (f->get_duration() >
   277                    ntop->getPrefs()->getIEC60870LearingPeriod()) {
   278                  FlowAlert *alert = NULL;
   279                  u_int16_t c_score = 50, s_score = 10;
   280
   281  #ifdef IEC60870_TRACE
   282                  ntop->getTrace()->traceEvent(TRACE_NORMAL,
   283                                               "Found new transition %u -> %u",
   284                                               last_type_i, type_id);
   285  #endif
   286                  char key[128], rsp[64];
   287                  snprintf(key, sizeof(key), CHECKS_IEC_INVALID_TRANSITION);
   288
   289                  if ((!ntop->getRedis()->get(key, rsp, sizeof(rsp))) &&
   290                      ((rsp[0] != '\0') && (!strcmp(rsp, "1"))))
   291                    alert = new IECInvalidTransitionAlert(NULL, f, packet_time,
   292                                                          last_type_i, type_id);
   293
   294                  if (alert) {
   295                    f->setPredominantAlertInfo(alert);
   296                    f->triggerAlertSync(alert, c_score, s_score);
   297                  }
   298
   299                  type_i_transitions[transition] = 2; /* Post Learning */
   300                } else
   301                  type_i_transitions[transition] = 1; /* During Learning */
   302              } else
   303                type_i_transitions[transition] = it->second + 1;
   304            }
   305
   306            if (!initial_run) {
   307              if (isMonitoringTypeId(last_type_i) && isMonitoringTypeId(type_id))
   308                transitions.m_to_m++;
   309              else if (isMonitoringTypeId(last_type_i) &&
   310                       isCommandTypeId(type_id))
   311                transitions.m_to_c++;
   312              else if (isCommandTypeId(last_type_i) &&
   313                       isMonitoringTypeId(type_id))
   314                transitions.c_to_m++;
   315              else if (isCommandTypeId(last_type_i) && isCommandTypeId(type_id))
   316                transitions.c_to_c++;
   317
   318              if ((invalid_command_transition_detected == false) &&
   319                  ((transitions.m_to_c > 20) || (transitions.c_to_m > 20) ||
   320                   (transitions.c_to_c > 5))) {
   321                /* https://github.com/ntop/ntopng/issues/6598 */
   322                FlowAlert *alert = NULL;
   323                u_int16_t c_score = CLIENT_ALERT_SCORE,
   324                          s_score = SERVER_ALERT_SCORE;
   325
   326                char key[128], rsp[64];
   327                snprintf(key, sizeof(key), CHECKS_IEC_INVALID_COMMAND_TRANSITION);
   328
   329                if ((!ntop->getRedis()->get(key, rsp, sizeof(rsp))) &&
   330                    ((rsp[0] != '\0') && (!strcmp(rsp, "1"))))
   331                  alert = new IECInvalidCommandTransitionAlert(
   332                      NULL, f, packet_time, transitions.m_to_c,
   333                      transitions.c_to_m, transitions.c_to_c);
   334
   335                if (alert) {
   336                  f->setPredominantAlertInfo(alert);
   337                  f->triggerAlertSync(alert, c_score, s_score);
   338                }
   339
   340                // ntop->getTrace()->traceEvent(TRACE_WARNING, "*** INVALID
   341                // TRANSITION %u -> %u", last_type_i, type_id);
   342
   343                invalid_command_transition_detected = true;
   344              }
   345            }
   346
   347            last_type_i = type_id;
   348
   349            it = typeid_uses.find(type_id);
   350
   351            if (it == typeid_uses.end())
   352              typeid_uses[type_id] = 1;
   353            else
   354              typeid_uses[type_id] = it->second + 1;
   355
   356            if (type_id < 64) {
   357              bit = ((u_int64_t)1) << type_id;
   358              if ((allowedTypeIDs[0] & bit) == 0)
   359                unexpected_typeid_alerted = true;
   360            } else if (type_id < 128) {
   361              bit = ((u_int64_t)1) << (type_id - 64);
   362
   363              if ((allowedTypeIDs[1] & bit) == 0)
   364                unexpected_typeid_alerted = true;
   365            }
   366
   367            if (unexpected_typeid_alerted) {
   368              FlowAlert *alert = NULL;
   369              u_int16_t c_score = CLIENT_ALERT_SCORE,
   370                        s_score = SERVER_ALERT_SCORE;
   371
   372              char key[128], rsp[64];
   373              snprintf(key, sizeof(key), CHECKS_IEC_UNEXPECTED_TYPE_ID);
   374
   375              if ((!ntop->getRedis()->get(key, rsp, sizeof(rsp))) &&
   376                  ((rsp[0] != '\0') && (!strcmp(rsp, "1"))))
   377                alert = new IECUnexpectedTypeIdAlert(NULL, f, type_id, asdu,
   378                                                     cause_tx, negative);
   379
   380              if (alert) {
   381                f->setPredominantAlertInfo(alert);
   382                f->triggerAlertSync(alert, c_score, s_score);
   383              }
   384            } /* unexpected_typeid_alerted */
   385            /* Discard typeIds 127..255 */
   386          } else /* payload_len < len */
   387            break;
   388        } else {
   389          // ntop->getTrace()->traceEvent(TRACE_WARNING, "*** short APDUs");
   390          break;
   391        }
   392
   393        if (payload[offset] == 0x68 /* IEC magic byte */)
   394          offset += 1; /* We skip the initial magic byte */
   395        else {
   396  #ifdef DEBUG_IEC60870
   397          ntop->getTrace()->traceEvent(
   398              TRACE_WARNING, "Skipping IEC entry: no magic byte @ offset %u",
   399              offset);
   400  #endif
   401          break;
   402        }
   403      } /* while */
   404
   405      lock.unlock(__FILE__, __LINE__);
   406    }
   407  }
