   411  void IEC104Stats::lua(lua_State *vm) {
   412    lua_newtable(vm);
   413
   414    lock.rdlock(__FILE__, __LINE__);
   415
   416    /* *************************** */
   417
   418    lua_newtable(vm);
   419
   420    for (std::unordered_map<u_int16_t, u_int32_t>::iterator it =
   421             typeid_uses.begin();
   422         it != typeid_uses.end(); ++it) {
   423      char buf[8];
   424
   425      snprintf(buf, sizeof(buf), "%u", it->first);
   426      lua_push_int32_table_entry(vm, buf, it->second);
   427    }
   428
   429    lua_pushstring(vm, "typeid");
   430    lua_insert(vm, -2);
   431    lua_settable(vm, -3);
   432
   433    /* *************************** */
   434
   435    lua_newtable(vm);
   436
   437    for (std::unordered_map<u_int16_t, u_int32_t>::iterator it =
   438             type_i_transitions.begin();
   439         it != type_i_transitions.end(); ++it) {
   440      char buf[8];
   441
   442      snprintf(buf, sizeof(buf), "%u,%u", (it->first >> 8), it->first & 0xFF);
   443      lua_push_int32_table_entry(vm, buf, it->second);
   444    }
   445
   446    lua_pushstring(vm, "typeid_transitions");
   447    lua_insert(vm, -2);
   448    lua_settable(vm, -3);
   449
   450    lock.unlock(__FILE__, __LINE__);
   451
   452    /* *************************** */
   453
   454    lua_newtable(vm);
   455    lua_push_int32_table_entry(vm, "type_i", stats.type_i);
   456    lua_push_int32_table_entry(vm, "type_s", stats.type_s);
   457    lua_push_int32_table_entry(vm, "type_u", stats.type_u);
   458    lua_push_int32_table_entry(vm, "type_other", stats.type_other);
   459    lua_push_int32_table_entry(vm, "forward_msgs", stats.forward_msgs);
   460    lua_push_int32_table_entry(vm, "reverse_msgs", stats.reverse_msgs);
   461    lua_push_int32_table_entry(vm, "retransmitted_msgs",
   462                               stats.retransmitted_msgs);
   463    lua_pushstring(vm, "stats");
   464    lua_insert(vm, -2);
   465    lua_settable(vm, -3);
   466
   467    /* *************************** */
   468
   469    lua_newtable(vm);
   470    lua_push_int32_table_entry(vm, "rx", pkt_lost.rx);
   471    lua_push_int32_table_entry(vm, "tx", pkt_lost.tx);
   472    lua_pushstring(vm, "pkt_lost");
   473    lua_insert(vm, -2);
   474    lua_settable(vm, -3);
   475
   476    /* *************************** */
   477
   478    lua_newtable(vm);
   479    lua_push_float_table_entry(vm, "average", ndpi_data_average(i_s_apdu));
   480    lua_push_float_table_entry(vm, "stddev", ndpi_data_stddev(i_s_apdu));
   481    lua_pushstring(vm, "ack_time");
   482    lua_insert(vm, -2);
   483    lua_settable(vm, -3);
   484
   485    /* *************************** */
   486
   487    lua_pushstring(vm, "iec104");
   488    lua_insert(vm, -2);
   489    lua_settable(vm, -3);
   490  }
