   493
   494  char *IEC104Stats::getFlowInfo(char *buf, u_int buf_len) {
   495    if (buf) {
   496      lock.rdlock(__FILE__, __LINE__);
   497      snprintf(buf, buf_len - 1, "%s", infobuf);
   498      lock.unlock(__FILE__, __LINE__);
   499    }
   500
   501    return (buf);
   502  }
   503
   504  /* *************************************** */
   505
   506  bool IEC104Stats::isMonitoringTypeId(u_int16_t tid) {
   507    return (((tid <= 40) || (tid == 70)) ? true : false);
   508  }
   509
   510  /* *************************************** */
   511
   512  bool IEC104Stats::isCommandTypeId(u_int16_t tid) {
   513    if (((tid >= 45) && (tid <= 64)) || ((tid >= 100) && (tid <= 107)))
   514      return (true);
   515    else
   516      return (false);
   517  }
